class SlideTabSection extends HTMLElement{constructor(){super(),this.slider=this.querySelector(".jsSlickSlider"),this.tabsSwitcher=this.querySelectorAll(".slide-tab__inner-switcher"),this.tabs=this.querySelectorAll(".slide-tab__inner-tab"),this.slider&&this.tabs.forEach(e=>{e.addEventListener("click",e=>{const t=e.target.dataset.slideSize,s=e.target.dataset.slideIndex,i=100/Number(t)*Number(s);$(this.slider).slick("slickGoTo",s),this.tabsSwitcher.forEach(e=>{e.style.left=`${i}%`})})})}}customElements.define("slide-tab-section",SlideTabSection);